let productStudioState={countryCode:'',blueprintId:null,launchId:null,stage:'foundation',studio:null};
async function loadProductStudioContext(){
  const q=new URLSearchParams();
  if(productStudioState.countryCode)q.set('country',productStudioState.countryCode);
  if(productStudioState.blueprintId)q.set('blueprintId',productStudioState.blueprintId);
  if(productStudioState.launchId)q.set('launchId',productStudioState.launchId);
  const d=await api(`/api/platform/admin/product-studio${q.toString()?`?${q}`:''}`);
  productStudioState.studio=d.studio||{};
  if(!productStudioState.blueprintId&&productStudioState.studio.country?.blueprint)productStudioState.blueprintId=productStudioState.studio.country.blueprint.id;
  if(!productStudioState.launchId&&productStudioState.studio.products?.selected)productStudioState.launchId=productStudioState.studio.products.selected.id;
  return productStudioState.studio;
}
function productStudioStageButtons(){return ['foundation','design','version','readiness','presentation'].map((x,i)=>`<button type="button" class="btn ${productStudioState.stage===x?'primary':'muted'}" data-ps-stage="${x}">${String(i+1).padStart(2,'0')} · ${x==='foundation'?'COUNTRY FOUNDATION':x==='design'?'PRODUCT DESIGN':x==='version'?'PRODUCT VERSION':x==='readiness'?'READINESS & LAUNCH':'UI PRESENTATION'}</button>`).join('')}
function productStudioConfigCard(configs,domain,key,title,desc,placeholder){return renderStudioCard(configs,domain,key,title,desc,placeholder).replace(/data-studio-save=/g,'data-ps-config-save=')}
function renderProductStudioPreview(studio){
  const p=studio.presentation||{},labels=p.labels||{},content=p.content||[],welcome=content.find(x=>x.key==='welcome')||content.find(x=>x.category==='welcome'),productName=content.find(x=>x.key==='product-name')||content.find(x=>x.category==='product-name');
  return `<div id="ps-preview" class="card section"><div class="section-head"><div><span class="eyebrow">RUNTIME PRESENTATION PREVIEW · READ ONLY</span><h3>${esc(productName?.body||'Mission Execution')}</h3><p class="sub">${esc(welcome?.body||'No ready welcome content has been prepared yet.')}</p></div><span class="pill ${content.length?'ok':'warn'}">${content.length?'CONTENT READY':'CONTENT INCOMPLETE'}</span></div><div class="grid three"><article class="card stat"><span>Primary language</span><strong>${esc((p.languages||[]).find(x=>x.primary)?.name||'—')}</strong><div class="mini">${esc((p.languages||[]).find(x=>x.primary)?.code||'')}</div></article><article class="card stat"><span>Visible navigation</span><strong>${Object.values(p.show||{}).filter(Boolean).length}</strong><div class="mini">${Object.entries(p.show||{}).filter(([,v])=>v).map(([k])=>esc(labels[k]||k)).join(' · ')||'None configured'}</div></article><article class="card stat"><span>Sectors</span><strong>${(p.sectors||[]).filter(x=>x.status==='ready').length}</strong><div class="mini">${(p.sectors||[]).map(x=>esc(x.name||x.code)).join(' · ')||'No sectors'}</div></article></div><section class="card section"><h3>Prepared UI content</h3><div class="table-wrap"><table class="table"><thead><tr><th>Key</th><th>Language</th><th>Category</th><th>Preview</th></tr></thead><tbody>${content.map(x=>`<tr><td><b>${esc(x.key)}</b></td><td>${esc(x.languageCode)}</td><td>${esc(x.category)}</td><td>${esc(String(x.body||'').slice(0,180))}${String(x.body||'').length>180?'…':''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Complete country content in the Foundation stage.</td></tr>'}</tbody></table></div></section></div>`;
}
async function saveProductStudioBlueprint(id,path,payload){if(!await ensureStepUp())return;try{await api(`/api/platform/admin/country-product-blueprints/${id}${path}`,{method:'POST',body:JSON.stringify(payload)});await renderProductStudio()}catch(e){alert(e.message)}}
async function prepareProductStudioBlueprint(id){if(!await ensureStepUp())return;try{const r=await api(`/api/platform/admin/country-product-blueprints/${id}/prepare`,{method:'POST',body:'{}'});productStudioState.blueprintId=id;await renderProductStudio();alert(r.blueprint.readiness?.ready?'Country foundation is READY.':`Still missing: ${(r.blueprint.readiness?.missing||[]).join(', ')}`)}catch(e){alert(e.message)}}
async function createProductStudioBlueprint(){state.dataEntryType='country_blueprint';state.dataEntryContext={countryCode:$('#ps-CountryCode')?.value||''};navigate('data-entry')}
async function createProductStudioLaunch(){if(!state.superAdmin){alert('Super Admin session required');return}const code=$('#ps-CountryCode')?.value,blueprintId=Number($('#ps-Blueprint')?.value||0)||null;if(!code||!blueprintId){$('#psLaunchMsg').textContent='Select a country and prepared foundation first.';return}const manifest={capabilities:($('#ps-Capabilities').value||'').split(',').map(x=>x.trim()).filter(Boolean),requiredConfigurations:($('#ps-RequiredConfigs').value||'').split(',').map(x=>x.trim()).filter(Boolean),eligibility:{organizationTypes:($('#ps-OrgTypes').value||'company').split(',').map(x=>x.trim()).filter(Boolean),sectors:[$('#ps-Sector').value||'general'],userClasses:($('#ps-UserClasses').value||'tenant_admin,driver,independent_executor').split(',').map(x=>x.trim()).filter(Boolean)},launchMessage:$('#ps-LaunchMessage').value||'ON Mission is available for this country.'};try{const r=await api('/api/platform/admin/country-product-launches/drafts',{method:'POST',body:JSON.stringify({countryCode:code,blueprintId,manifest,reason:'Prepared in Unified Product Studio'})});const launch=r.launch||r;productStudioState.countryCode=code;productStudioState.blueprintId=blueprintId;productStudioState.launchId=launch.id;productStudioState.stage='readiness';await renderProductStudio()}catch(e){$('#psLaunchMsg').textContent=e.message||'Product version creation failed'}}
async function saveProductStudioConfig(domain,key){if(!state.superAdmin){alert('Super Admin session required');return}const ta=document.querySelector(`[data-studio-payload="${domain}:${key}"]`);if(!ta)return;let payload;try{payload=JSON.parse(ta.value)}catch{alert('Configuration must be valid JSON');return}try{await api('/api/platform/admin/platform-configurations/drafts',{method:'POST',body:JSON.stringify({domainCode:domain,configKey:key,version:'auto',payload,reason:`Prepared ${domain} / ${key} in Unified Product Studio`})});await refreshData();await renderProductStudio()}catch(e){alert(e.message)}}

let productDefinitionState={id:null,definition:null};
async function loadProductDefinitions(country='',sector=''){const q=new URLSearchParams();if(country)q.set('country',country);if(sector)q.set('sector',sector);const d=await api(`/api/platform/admin/product-definitions?${q}`);return d.definitions||[]}
async function loadProductDefinition(id){const d=await api(`/api/platform/admin/product-definitions/${id}`);productDefinitionState={id:Number(id),definition:d.definition};return d.definition}
async function createStudioProductDefinition(){if(!await ensureStepUp())return;const country=productStudioState.countryCode;const launch=Number(productStudioState.launchId||0)||null;const b=Number(productStudioState.blueprintId||0)||null;if(!country||!launch){alert('Create or select a product version first.');return}const sector=prompt('Product sector:','logistics');if(!sector)return;const name=prompt('Product name:',`${country} ${sector}`);if(!name)return;try{const r=await api('/api/platform/admin/product-definitions',{method:'POST',body:JSON.stringify({productKey:`${country.toLowerCase()}-${sector.toLowerCase()}`,name,description:`Composable product for ${country} / ${sector}`,countryCode:country,sectorCode:sector,launchId:launch,baseDefinitionId:null})});productDefinitionState={id:r.definition.id,definition:r.definition};await renderProductStudio()}catch(e){alert(e.message||'Product definition could not be created')}}
async function saveStudioComponent(){if(!productDefinitionState.id)return;if(!await ensureStepUp())return;const type=$('#ps-ComponentType')?.value,key=$('#ps-ComponentKey')?.value;let payload={};try{payload=JSON.parse($('#ps-ComponentPayload')?.value||'{}')}catch{alert('Component JSON is invalid.');return}try{await api(`/api/platform/admin/product-definitions/${productDefinitionState.id}/components`,{method:'POST',body:JSON.stringify({componentType:type,componentKey:key,payload,status:'draft'})});await loadProductDefinition(productDefinitionState.id);await renderProductStudio()}catch(e){alert(e.message||'Component could not be saved')}}
async function importStudioComponents(){if(!productDefinitionState.id)return;if(!await ensureStepUp())return;let items;try{items=JSON.parse($('#ps-ComponentImport')?.value||'[]')}catch{alert('Import JSON is invalid.');return}if(!Array.isArray(items))items=items.components||items.items||[];try{await api(`/api/platform/admin/product-definitions/${productDefinitionState.id}/import`,{method:'POST',body:JSON.stringify({components:items})});await loadProductDefinition(productDefinitionState.id);await renderProductStudio()}catch(e){alert(e.message||'Import failed')}}
async function compileStudioProduct(){if(!productDefinitionState.id){alert('Create a product definition first.');return}if(!await ensureStepUp())return;try{const r=await api(`/api/platform/admin/product-definitions/${productDefinitionState.id}/compile`,{method:'POST',body:'{}'});productDefinitionState.definition=r.definition;await renderProductStudio();alert(`Product definition compiled. Manifest hash: ${r.manifestHash}`)}catch(e){alert(e.message||'Compilation failed')}}

